const input = $input.all()[0].json;
const profile = input.founder_profile || {};
const investors = input.investors || [];
const connectedFounders = input.connected_founders || [];

const networkProfiles = [
  ...investors.map(i => ({ name: i.name, profile_url: i.profile_url, type: 'investor' })),
  ...connectedFounders.map(f => ({ name: f.name, profile_url: f.profile_url, type: 'founder' }))
];

const eventKeywords = [
  ...(profile.industry_tags || []),
  ...(profile.preferred_event_types || []),
  profile.funding_stage ? profile.funding_stage.replace('_', ' ') : '',
  'startup',
  'venture capital',
  'pitch',
  'demo day',
  'networking'
].filter(Boolean);

const locations = profile.geo_preferences || [profile.location].filter(Boolean);

return [{
  json: {
    event_keywords: [...new Set(eventKeywords)],
    locations: locations,
    network_profiles: networkProfiles,
    founder_profile: profile,
    sources: ['linkedin_events', 'eventbrite', 'meetup']
  }
}];

const input = $input.all()[0].json;
return input.sources.map(source => ({
  json: {
    source: source,
    event_keywords: input.event_keywords,
    locations: input.locations,
    network_profiles: input.network_profiles,
    founder_profile: input.founder_profile
  }
}));

const items = $input.all();
const allEvents = [];

for (const item of items) {
  const response = item.json;
  let events = response?.events || response?.result?.events || response?.data?.events || [];
  allEvents.push(...events);
}

const firstItem = $input.first();
const networkProfiles = firstItem?.json?.network_profiles || [];
const founderProfile = firstItem?.json?.founder_profile || {};
const networkNames = new Set(networkProfiles.map(p => p.name.toLowerCase()));
const industryTags = new Set((founderProfile.industry_tags || []).map(t => t.toLowerCase()));
const eventTypes = new Set((founderProfile.preferred_event_types || []).map(t => t.toLowerCase()));

const seen = new Set();
const scoredEvents = [];

for (const evt of allEvents) {
  const key = `${(evt.event_name || '').toLowerCase()}_${evt.date}`;
  if (seen.has(key)) continue;
  seen.add(key);

  const attendees = (evt.attendees || []).map(a => a.toLowerCase());
  const attendeesFromNetwork = attendees.filter(a => {
    for (const name of networkNames) {
      if (a.includes(name) || name.includes(a)) return true;
    }
    return false;
  });

  const desc = ((evt.description || '') + ' ' + (evt.event_name || '')).toLowerCase();
  let relevancyScore = 0;
  for (const tag of industryTags) { if (desc.includes(tag)) relevancyScore += 2; }
  for (const et of eventTypes) { if (desc.includes(et)) relevancyScore += 3; }
  if (desc.includes('startup')) relevancyScore += 1;
  if (desc.includes('investor') || desc.includes('pitch') || desc.includes('demo day')) relevancyScore += 2;

  const connectionScore = attendeesFromNetwork.length * 5;

  scoredEvents.push({
    event_name: evt.event_name || 'Unknown Event',
    date: evt.date || '',
    location: evt.location || '',
    url: evt.url || '',
    attendees_from_network: attendeesFromNetwork,
    relevancy_score: relevancyScore,
    connection_score: connectionScore,
    combined_score: relevancyScore + connectionScore,
    source: evt.source || ''
  });
}

scoredEvents.sort((a, b) => b.combined_score - a.combined_score);

return [{
  json: {
    status: 'success',
    events: scoredEvents,
    count: scoredEvents.length
  }
}];
